  const p=s.particles[i];p.raw=(particleRandom(s)^(orbitBytes?((orbitHash>>>(i%32))^orbitBytes[(s.tick*s.particles.length+i)%orbitBytes.length]):0))&1;p.prayer=Number(prayerBits[(s.tick*s.particles.length+i)%prayerBits.length]);p.proposed=p.raw^p.prayer;
