  const candidate=p.x+(p.proposed?speed:-speed);
  p.label=s.review?(candidate<0||candidate>4095?'evil':'good'):'unknown';
  const drift=(particleRandom(s)%33)-16;preParticles.push({...p,vx:p.proposed?speed:-speed,vy:drift,output:p.proposed});
